'use strict';

const { createContentApiRoutesFactory } = require('@strapi/utils');

const ratingRoutes = (strapi) => {
  return [
    { method: 'GET', path: '/ratings', handler: 'rating.find' },
    { method: 'POST', path: '/ratings', handler: 'rating.create' },
  ];
};

module.exports = createContentApiRoutesFactory(() => [...ratingRoutes(strapi)]);
